(()=>{'use strict';const slug='reading-list',key='items',max=120;let rt,state={items:[],filter:'all',query:'',sort:'updated',editing:null},queue=Promise.resolve();const $=id=>document.getElementById(id);const id=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`,now=()=>new Date().toISOString(),safe=s=>{const d=document.createElement('div');d.textContent=String(s||'');return d.innerHTML},clean=s=>String(s||'').trim().slice(0,max);function toast(s,bad=false){const e=$('toast');e.textContent=s;e.style.borderColor=bad?'rgba(255,120,131,.5)':'rgba(49,222,197,.4)';e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),3800)}function msg(e,f){if(/nonce|rest_cookie/i.test(`${e?.code} ${e?.message}`))return'WordPress could not verify that request. Refresh and try again.';if(e?.status===401)return'Your session expired. Sign in again.';if(e?.status===403)return'WordPress denied that action.';if(e?.status===413)return'The saved data is too large. Remove some notes or entries.';if(e?.status===429)return'Too many saves. Wait a moment and try again.';return e?.message||f}function requireRuntime(){const x=window.oddApp;if(!x||x.apiVersion!==1||x.slug!==slug||!x.storage||typeof x.storage.get!=='function'||typeof x.storage.set!=='function'||typeof x.confirm!=='function')throw Error('ODD app runtime v1 is unavailable. Update ODD and reopen this app.');return x}async function load(){try{rt=requireRuntime();const v=await rt.storage.get(key);state.items=Array.isArray(v)?v:[];$('loading').hidden=true;render()}catch(e){$('loading').textContent=msg(e,'Could not load private storage.');toast(msg(e,'Storage unavailable.'),true)}}function save(){queue=queue.catch(()=>{}).then(()=>rt.storage.set(key,state.items));return queue}function validUrl(raw){try{const u=new URL(raw);return['http:','https:'].includes(u.protocol)&&!u.username&&!u.password&&u.hostname.length<=253&&u.href.length<=2000?u.href:''}catch(e){return''}}function filtered(){const q=state.query.toLowerCase();return state.items.filter(i=>(state.filter==='all'||i.status===state.filter||state.filter==='archived'&&i.archived)&&(!q||`${i.title} ${i.url} ${i.notes} ${(i.tags||[]).join(' ')}`.toLowerCase().includes(q))).sort((a,b)=>state.sort==='title'?a.title.localeCompare(b.title):state.sort==='priority'?Number(b.priority)-Number(a.priority)||String(b.updated).localeCompare(String(a.updated)):state.sort==='date'?String(b.date).localeCompare(String(a.date)):String(b.updated).localeCompare(String(a.updated)))}function render(){const all=state.items.length;$('total').textContent=all;['all','unread','reading','finished','archived'].forEach(f=>{const b=document.querySelector(`[data-filter="${f}"] b`);if(b)b.textContent=f==='all'?all:state.items.filter(i=>f==='archived'?i.archived:i.status===f).length});document.querySelectorAll('.filter').forEach(b=>b.classList.toggle('active',b.dataset.filter===state.filter));const list=$('entries');list.replaceChildren();const data=filtered();$('empty').hidden=data.length>0;data.forEach(i=>{const c=document.createElement('article');c.className='entry';c.innerHTML=`<div class="entry-top"><small>${i.priority?'HIGH PRIORITY':'READING QUEUE'}</small><span>${safe(i.archived?'archived':i.status)}</span></div><h3>${safe(i.title)}</h3><p>${safe(i.notes||i.url)}</p><div class="entry-foot"><span>${(i.tags||[]).slice(0,2).map(safe).join(', ')||'No tags'}</span><div class="entry-actions"><button data-open="${i.id}">Open</button><button data-edit="${i.id}">Edit</button><button class="danger" data-delete="${i.id}">Delete</button></div></div>`;list.append(c)})}function openItem(item){state.editing=item?.id||null;$('dialogTitle').textContent=item?'Edit saved link':'Save a link';$('url').value=item?.url||'';$('title').value=item?.title||'';$('notes').value=item?.notes||'';$('tags').value=(item?.tags||[]).join(', ');$('status').value=item?.status||'unread';$('priority').value=item?.priority?'1':'0';$('date').value=item?.date||'';$('dialog').showModal();$('url').focus()}function close(){$('dialog').close();state.editing=null}async function submit(e){e.preventDefault();const url=validUrl($('url').value);if(!url){toast('Use a valid http:// or https:// URL without credentials.',true);$('url').focus();return}const title=clean($('title').value)||url;const item={id:state.editing||id(),url,title,notes:clean($('notes').value),tags:$('tags').value.split(',').map(clean).filter(Boolean).slice(0,20),status:$('status').value,priority:$('priority').value==='1',date:$('date').value,archived:false,updated:now()};const ix=state.items.findIndex(x=>x.id===item.id);if(ix<0)state.items.unshift(item);else state.items[ix]=item;try{await save()}catch(e){toast(msg(e,'Could not save your changes.'),true);return}close();render();toast(ix<0?'Link saved':'Link updated')}function download(type){const data=filtered();const rows=type==='csv'?[['title','url','notes','tags','status','priority','date','archived'],...data.map(i=>[i.title,i.url,i.notes,(i.tags||[]).join('; '),i.status,i.priority?'high':'normal',i.date,i.archived?'yes':'no'])]:data;const text=type==='csv'?rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'):JSON.stringify({version:1,exportedAt:now(),items:data},null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:type==='csv'?'text/csv':'application/json'}));a.download=`odd-reading-list.${type}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast(`Exported ${data.length} link${data.length===1?'':'s'}`)}document.addEventListener('DOMContentLoaded',()=>{ $('search').oninput=e=>{state.query=e.target.value;render()};$('sort').onchange=e=>{state.sort=e.target.value;render()};document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});$('newItem').onclick=()=>openItem();$('form').onsubmit=submit;['close','cancel'].forEach(i=>$(i).onclick=close);$('exportJson').onclick=()=>download('json');$('exportCsv').onclick=()=>download('csv');$('entries').onclick=async e=>{const o=e.target.closest('[data-open]'),edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');const item=state.items.find(i=>i.id===(o||edit||del)?.dataset?.[o?'open':edit?'edit':'delete']);if(o){window.open(item.url,'_blank','noopener,noreferrer');return}if(edit)openItem(item);if(del&&item&&await rt.confirm(`Delete “${item.title}”?`)){state.items=state.items.filter(i=>i.id!==item.id);await save();render();toast('Link deleted')}};load()})})();
